// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp, uint256 past) public {
        vm.assume(timestamp > past);
        vm.assume(timestamp < type(uint256).max);
        vm.assume(blockNumber < type(uint256).max - 14);
        vm.roll(blockNumber);
        vm.warp(timestamp);
        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        assertEq(c.pastBlockTime(), timestamp + 1);
    }
}
